const d = input.trim().split(/\s+/).map(Number);
const n = d[0];
const a = d.slice(1, 1 + n);
const m = d[1 + n];
const b = d.slice(2 + n, 2 + n + m);
const rank = new Map();
b.forEach((v, i) => rank.set(v, i));
a.sort((x, y) => {
  const rx = rank.has(x), ry = rank.has(y);
  if (rx && ry) return rank.get(x) - rank.get(y);
  if (rx) return -1;
  if (ry) return 1;
  return x - y;
});
